using Microsoft.EntityFrameworkCore;using SenorArroz.Application.Common.Interfaces;using SenorArroz.Domain.Entities;using SenorArroz.Domain.Enums;
namespace SenorArroz.Application.Common.Services;
public class WhatsAppOrderDraftCalculator(IApplicationDbContext db):IWhatsAppOrderDraftCalculator
{
 public async Task<WhatsAppOrderDraft> Recalculate(int id,CancellationToken ct=default){var draft=await db.WhatsAppOrderDrafts.Include(x=>x.Items).ThenInclude(x=>x.Product).Include(x=>x.Address).ThenInclude(x=>x!.Neighborhood).FirstAsync(x=>x.Id==id,ct);EnsureEditable(draft);foreach(var item in draft.Items){item.UnitPrice=item.Product.Price;item.Subtotal=checked(item.UnitPrice*item.Quantity);}draft.Subtotal=draft.Items.Sum(x=>x.Subtotal);draft.DeliveryFee=draft.OrderType==OrderType.Delivery?draft.Address?.Neighborhood.DeliveryFee??0:0;draft.DiscountTotal=0;draft.Total=Math.Max(0,draft.Subtotal+draft.DeliveryFee-draft.DiscountTotal);draft.ChangeAmount=draft.PaymentMethod=="cash"&&draft.CashReceived.HasValue&&draft.CashReceived>=draft.Total?draft.CashReceived-draft.Total:null;draft.Status=draft.CustomerId is null?WhatsAppOrderDraftStatus.AwaitingCustomerData:draft.Items.Count==0?WhatsAppOrderDraftStatus.Building:draft.OrderType is null?WhatsAppOrderDraftStatus.Building:draft.OrderType==OrderType.Delivery&&draft.AddressId is null?WhatsAppOrderDraftStatus.AwaitingAddress:string.IsNullOrWhiteSpace(draft.PaymentMethod)?WhatsAppOrderDraftStatus.AwaitingPayment:WhatsAppOrderDraftStatus.Building;draft.Version++;await db.SaveChangesAsync(ct);return draft;}
 public static void EnsureEditable(WhatsAppOrderDraft d){if(d.Status is WhatsAppOrderDraftStatus.Cancelled or WhatsAppOrderDraftStatus.Confirmed or WhatsAppOrderDraftStatus.ConvertedToOrder or WhatsAppOrderDraftStatus.Expired)throw new InvalidOperationException("El borrador ya no se puede modificar.");}
}
